const item = $input.first();
const body = item.json.body || item.json;
const binary = item.binary || {};
const binaryKeys = Object.keys(binary);

if (!binaryKeys.length) {
  throw new Error('Nenhum arquivo enviado. Use o campo "video" no formulário.');
}

return {
  json: {
    ...body,
    job_started_at: new Date().toISOString(),
  },
  binary: {
    data: binary[binaryKeys[0]],
  },
};

const form = $('Iniciar Job').first().json;

const parseList = (value) => {
  if (Array.isArray(value)) return value;
  try {
    const parsed = JSON.parse(value || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
};

const templates = parseList(form.templates)
  .map((name) => String(name).trim())
  .filter(Boolean);

if (!templates.length) {
  throw new Error('Nenhum template selecionado.');
}

const mode = String(form.background_mode || 'none')
  .trim()
  .toLowerCase();
const selected = parseList(form.background_keys);

const available = $('Listar Backgrounds').all()
  .map((item) => item.json.Key || item.json.key || '')
  .filter((key) => /\.(mp4|mov|webm|m4v)$/i.test(key))
  .sort();

const sourceBinary = $('Iniciar Job').first().binary?.data || {};
const sourceMime = String(sourceBinary.mimeType || '').toLowerCase();
const sourceHasVideo =
  sourceMime.startsWith('video/') ||
  /^(mp4|mov|webm|m4v|mkv)$/i.test(String(sourceBinary.fileExtension || ''));

const outputAspectRaw = String(form.output_aspect || '9:16')
  .trim()
  .toLowerCase();
const outputAspect = ['original', '9:16', '4:5', '1:1', '16:9', '4:3'].includes(
  outputAspectRaw,
)
  ? outputAspectRaw
  : '9:16';
const outputQuality = /1440/.test(String(form.output_quality || '1080'))
  ? '1440'
  : '1080';
const fillMode =
  String(form.fill_mode || 'contain').trim().toLowerCase() === 'cover'
    ? 'cover'
    : 'contain';

let backgrounds;
let renderMode;
let varied = false;

if (mode === 'none') {
  backgrounds = [null];
  renderMode = 'none';
} else if (mode === 'source') {
  if (!sourceHasVideo) {
    throw new Error(
      'O modo "vídeo enviado" exige um arquivo de vídeo. Envie um vídeo ou escolha outro modo de fundo.',
    );
  }
  backgrounds = [null];
  renderMode = 'source';
} else if (mode === 'folder_all') {
  backgrounds = available;
  renderMode = 'fixed';
} else if (mode === 'folder_selected') {
  backgrounds = selected.filter((key) => available.includes(key));
  renderMode = 'fixed';
} else if (mode === 'folder_varied') {
  backgrounds = selected.filter((key) => available.includes(key));
  renderMode = 'fixed';
  varied = true;
} else if (mode === 'fixed') {
  backgrounds = selected.slice(0, 1).filter((key) => available.includes(key));
  renderMode = 'fixed';
} else {
  backgrounds = [null];
  renderMode = 'none';
}

if (!backgrounds.length) {
  throw new Error('Nenhum background encontrado para o modo selecionado.');
}

const transcript = $('Transcrever (WhisperX)').first().json;
const words = (transcript.words || [])
  .filter((word) => word && word.word)
  .map((word) => ({
    word: String(word.word),
    start: Number(word.start),
    end: Number(word.end),
  }))
  .filter(
    (word) =>
      Number.isFinite(word.start) &&
      Number.isFinite(word.end) &&
      word.end > word.start,
  );

if (!words.length) {
  throw new Error('WhisperX returned no words.');
}

const lastWord = words[words.length - 1];
const duration = Number((lastWord.end + 0.5).toFixed(3));
const filename = sourceBinary.fileName || 'input';
const jobStartedAt = form.job_started_at || new Date().toISOString();
const jobId = $execution.id;

const slugify = (value) =>
  String(value || '')
    .split('/')
    .pop()
    .replace(/\.[^.]+$/, '')
    .replace(/[^a-zA-Z0-9._-]+/g, '-');

function shuffle(list) {
  const copy = [...list];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

const buildItem = (background, runIndex, templateName) => {
  const templateFile = templateName.toLowerCase().endsWith('.html')
    ? templateName
    : templateName + '.html';
  const templateSlug = slugify(templateFile);
  const backgroundSlug = background
    ? slugify(background)
    : renderMode === 'source'
      ? 'source'
      : 'nobg';
  const s3Key =
    jobId +
    '_' +
    runIndex +
    '_' +
    backgroundSlug +
    '_' +
    templateSlug +
    '.mp4';

  return {
    json: {
      run_index: runIndex,
      background_mode: renderMode,
      background_file: renderMode === 'source' ? filename : background || '',
      background_key: background || '',
      template_file: templateFile,
      template_name: templateSlug,
      template_style: '{}',
      transcript_data: JSON.stringify(words),
      original_filename: filename,
      source_video_key: '',
      bucket: 'lyrics',
      s3_key: s3Key,
      duration,
      word_count: words.length,
      language: form.language || 'pt',
      segmentation_mode: form.segmentation_mode || 'lyrics',
      output_aspect: outputAspect,
      output_quality: outputQuality,
      fill_mode: fillMode,
      job_started_at: jobStartedAt,
      s3_public_base_url: 'http://localhost:8333',
    },
  };
};

if (varied) {
  let pool = shuffle(templates);
  let cursor = 0;

  return backgrounds.map((background, index) => {
    if (cursor >= pool.length) {
      pool = shuffle(templates);
      cursor = 0;
    }
    const templateName = pool[cursor++];
    return buildItem(background, index, templateName);
  });
}

return backgrounds.flatMap((background, backgroundIndex) =>
  templates.map((templateName, templateIndex) =>
    buildItem(
      background,
      backgroundIndex * templates.length + templateIndex,
      templateName,
    ),
  ),
);

const item = $input.first();
const original = $('Iniciar Job').first();

return {
  json: {
    ...item.json,
    render_started_at: new Date().toISOString(),
  },
