};

const base = $('Reanexar Binário').item.json;
const binary = $('Renderizar com HyperFrames').item.binary || {};
const fileData = binary.data || {};
const finishedAt = new Date().toISOString();
const startedAt = base.render_started_at || finishedAt;
const startedMs = Date.parse(startedAt);
const finishedMs = Date.parse(finishedAt);
const bucket = base.bucket || 'lyrics';
const baseUrl = String(
  base.s3_public_base_url || 'http://localhost:8333',
).replace(/\/+$/, '');
const executionId = String($execution.id);
const workflowId = String($workflow.id || '');

return {
  json: {
    execution_id: executionId,
    execution_url: workflowId
      ? 'http://localhost:5678/workflow/' +
        workflowId +
        '/executions/' +
        executionId
      : '',
    run_index: String(base.run_index ?? ''),
    background_file: base.background_file || '',
    template_file: base.template_file || '',
    template_name: base.template_name || '',
    original_filename: base.original_filename || '',
    source_video_key: base.source_video_key || '',
    bucket,
    s3_key: $('Crypto').first().json.video +".mp4" || '',
    video_url: base.s3_key ? baseUrl + '/' + bucket + '/' + $('Crypto').first().json.video +".mp4" : '',
    file_size_bytes: String(fileData.fileSize ?? ''),
    duration_seconds: String(base.duration ?? ''),
    word_count: String(base.word_count ?? ''),
    status: 'success',
    render_started_at: startedAt,
    render_finished_at: finishedAt,
    render_seconds: Number.isFinite(startedMs)
      ? ((finishedMs - startedMs) / 1000).toFixed(2)
      : '',
    job_started_at: base.job_started_at || '',
    job_finished_at: finishedAt,
    language: base.language || '',
    segmentation_mode: base.segmentation_mode || '',
  },
};

const inputItem = $input.first();
const inputJson = inputItem.json || {};

let base = {};
try {
  base = $('Reanexar Binário').item.json || {};
} catch (e) {
  base = {};
}

const source = { ...inputJson, ...base };
const uploaded = Boolean(inputJson.video_url && inputJson.s3_key);
const now = new Date().toISOString();
const startedAt = source.render_started_at || '';
const startedMs = Date.parse(startedAt);
const executionId = String($execution.id);
