return {
  json: {
    execution_id: executionId,
    execution_url: workflowId
      ? 'http://localhost:5678/workflow/' +
        workflowId +
        '/executions/' +
        executionId
      : '',
    run_index: String(source.run_index ?? ''),
    background_file: source.background_file || inputJson.background_file || '',
    template_file: source.template_file || '',
    template_name: source.template_name || '',
    original_filename: source.original_filename || '',
    source_video_key: source.source_video_key || '',
    bucket,
    s3_key: uploaded ? inputJson.s3_key : '',
    video_url: uploaded ? inputJson.video_url : '',
    file_size_bytes: uploaded
      ? String(inputJson.file_size_bytes ?? '')
      : '',
    duration_seconds: String(source.duration ?? ''),
    word_count: String(source.word_count ?? ''),
    status: 'error',
    render_started_at: startedAt,
    render_finished_at: now,
    render_seconds: Number.isFinite(startedMs)
      ? ((Date.parse(now) - startedMs) / 1000).toFixed(2)
      : '',
    job_started_at: source.job_started_at || '',
    job_finished_at: now,
    language: source.language || '',
    segmentation_mode: source.segmentation_mode || '',
  },
};

const transcript = $('Transcrever (WhisperX)').first().json || {};
const duration = Number(transcript.duration || transcript.metadata?.duration || 0);
if (!Number.isFinite(duration) || duration <= 0) return $input.all();
return $input.all().map((item) => ({
  json: { ...item.json, duration: Number(duration.toFixed(3)) },
}));

const input = $input.first().json || {};
const xml = String(input.data || input.body || '');
const keys = [...xml.matchAll(/<Key>([\s\S]*?)<\/Key>/g)].map((match) => match[1]);
const filtered = keys.filter(
  (key) => key.startsWith('jobs/') && !key.endsWith('/'),
);
return filtered.map((key) => ({ json: { key } }));

